// Original code for RetroPixels (PixelU-Wii). Not derived from Dolphin.
//
// The config.h that Bochs' disassembler (bochs/disasm/disasm.h) includes. In
// Bochs it is generated by the configure script for the whole emulator; the
// disassembler on its own only needs Bochs' fixed-width integer names and a
// few helper macros, given here for any C++ compiler with <cstdint>.

#ifndef PIXELU_BOCHS_DISASM_CONFIG_H
#define PIXELU_BOCHS_DISASM_CONFIG_H

#include <cstdint>

typedef std::int8_t Bit8s;
typedef std::uint8_t Bit8u;
typedef std::int16_t Bit16s;
typedef std::uint16_t Bit16u;
typedef std::int32_t Bit32s;
typedef std::uint32_t Bit32u;
typedef std::int64_t Bit64s;
typedef std::uint64_t Bit64u;

typedef bool bx_bool;
// Addresses are 64 bits wide (Bochs' x86-64 build).
typedef Bit64u bx_address;

#define BX_CPP_INLINE inline
#define BX_CONST64(x) (x##LL)
#define GET32L(val64) ((Bit32u)(((Bit64u)(val64)) & 0xFFFFFFFF))
#define GET32H(val64) ((Bit32u)(((Bit64u)(val64)) >> 32))

// Not part of the Bochs debugger: no symbol lookups through it.
#define BX_DEBUGGER 0

#endif
